#include <stdio.h>
#include <string.h>

int isUpper(char c) {
    return c >= 'A' && c <= 'Z';
}

int isDigit(char c) {
    return c >= '0' && c <= '9';
}

int main(void) {
    char s[20];

    if (scanf("%19s", s) != 1) return 0;

    int n = strlen(s);

    if (n == 8) {
        int ok = 1;

        for (int i = 0; i < 3; i++) {
            if (!isUpper(s[i])) ok = 0;
        }
        if (s[3] != '-') ok = 0;
        for (int i = 4; i < 8; i++) {
            if (!isDigit(s[i])) ok = 0;
        }

        if (ok) {
            printf("1\n");
            return 0;
        }
    }

    if (n == 7) {
        int ok = 1;

        for (int i = 0; i < 3; i++) {
            if (!isUpper(s[i])) ok = 0;
        }
        if (!isDigit(s[3])) ok = 0;
        if (!isUpper(s[4])) ok = 0;
        for (int i = 5; i < 7; i++) {
            if (!isDigit(s[i])) ok = 0;
        }

        if (ok) {
            printf("2\n");
            return 0;
        }
    }

    printf("0\n");
    return 0;
}
